INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('tactician-the-menagerie','Tactician','traveller','Goodpart',NULL,NULL,'The Menagerie','{"slug":"tactician-the-menagerie","name":"Tactician","team":"traveller","ability":"Each night*, choose a player. You may give them advice: they learn this, and whether it will help your team win the game.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Let your plans be dark and impenetrable as night, and when you move, fall like a thunderbolt.","lede":"The Tactician advises its troops to help win the war for its own side.","howToRun":["If the Tactician provides advice that is too specific, you may play a mediating role in offering advice that is less confirming or against the spirit of the character."],"tips":["Your advice can be used for good or ill, but remember that the Storyteller will always tell the player you''ve chosen whether the advice will help your team win! This means players will never be inclined to trust you fully, so speaking with your fellow players and gathering useful information is crucial to succeeding in your role.","If evil, your advice can be used to guide evil kills, or drive good players away from the truth, so be creative with the advice you offer, consider reinforcing wrong worlds, and drive town towards incorrect conclusions. You''ll be found out eventually, but at least you''ll have done your damage."],"bluffing":[],"fighting":[],"examples":["The Tactician is in play, and is good. On Night 2, they provide advice to the Chef, telling them to look for an Outsider. The Chef receives this advice and a thumbs up. The Chef determines that the Recluse is sat next to a Minion."],"firstNight":0,"firstNightReminder":"","otherNight":8,"otherNightReminder":"The Tactician chooses a player and offers advice to the Storyteller. The Storyteller wakes that player, provides that advice, and gives a thumbs up or down.","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/tac.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/tacg.png","imageAlt2":"https://menagerie.towerrangers.net/images/tace.png"}','published','the-menagerie/tactician',datetime('now'),datetime('now')),
('taxidermist-the-menagerie','Taxidermist','traveller','Goodpart',NULL,NULL,'The Menagerie','{"slug":"taxidermist-the-menagerie","name":"Taxidermist","team":"traveller","ability":"Dead votes can be used to nominate. If you die, travel out or are exiled, choose 1-3 players: they regain their vote token :reminder:.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"The difference between the tax man and the taxidermist is that the taxidermist leaves the skin.","lede":"The Taxidermist allows the dead to nominate, and generously hands back ghost votes as a parting gift.","howToRun":["Remember to prompt the Taxidermist to choose their players prior to their departure.","If the Taxidermist has to leave suddenly, you may redistribute ghost votes arbitrarily."],"tips":["Whether you''re good or evil, you''re in play, so dead players can nominate! This is universally useful, and may provoke dead players to spend their ghost vote if they truly believe in a nomination.","Of course, if you are a good Taxidermist, you may want to reward their bold play by \"refunding\" their ghost vote upon your travelling out. But if you''re evil? You may want to persuade players to spend their ghost vote, and give as few back as possible in return, burning up ghost votes that would otherwise be used in the closing stages of the game."],"bluffing":[],"fighting":[],"examples":["The Taxidermist is in play, and is good. Three players spend ghost votes to nominate during the game, and the Taxidermist refunds two of them, suspecting the third to be an evil player. Those two players are free to vote again."],"firstNight":0,"firstNightReminder":"","otherNight":0,"otherNightReminder":"","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/tax.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/taxg.png","imageAlt2":"https://menagerie.towerrangers.net/images/taxe.png"}','published','the-menagerie/taxidermist',datetime('now'),datetime('now')),
('peanut-gallery','Peanut Gallery','fabled','Goodpart',NULL,NULL,'The Menagerie','{"slug":"peanut-gallery","name":"Peanut Gallery","team":"fabled","ability":"Before characters are drawn, spectators choose one player. They win and lose with that player.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"We''re #1! We''re #1! We''re #1!","lede":"The Peanut Gallery win and lose with their Chosen One.","howToRun":["Mark the player chosen by spectators as the \"Chosen One\" and announce it at the commencement of the game."],"tips":["Don''t worry, this doesn''t impact the game at all - it''s just a bit of fun, and a way for spectators to interact with the game. It''s okay if you''re into horse racing instead."],"bluffing":[],"fighting":[],"examples":["Michael is the Chosen One for this game, and is the Savant. The Demon is killed on Day 4, so Michael - and the spectators - win. Hooray."],"firstNight":0,"firstNightReminder":"","otherNight":0,"otherNightReminder":"","reminders":["Chosen One"],"setup":true,"image":"https://menagerie.towerrangers.net/images/nut.png","curata":false}','published','the-menagerie/peanut-gallery',datetime('now'),datetime('now')),
('mercy-society','Mercy Society','fabled','Goodpart',NULL,NULL,'The Menagerie','{"slug":"mercy-society","name":"Mercy Society","team":"fabled","ability":"Each night, one player learns which alignment the Storyteller believes is winning: good, evil, or neither. Drunk or poisoned players may receive false info.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Inter arma caritas. Per humanitatem ad pacem.","lede":"The Mercy Society gives players updates on who is winning the game, but doesn''t favour a team.","howToRun":["Try to balance the Mercy Society''s ability between good and evil, as much as possible - and as much as necessary, depending on the game state.","It is recommended not to run the \"Five Star General\" variant of the General, and stick to just good, evil or neither.","If a General is in play, consider giving evil information on the same night the General receives false info, so that they have a chance to bluff what they receive."],"tips":["This Fabled is meant to guide players, both good and evil. Learning that one side is winning might give some clues about whether a particular night death was impactful, or whether a particular execution was worthwhile - information useful to both sides. Unlike the General, who generally plays for good, the Mercy Society is neutral, and will dispense its advice to both sides.","If a General is in play, the Mercy Society ensures the General receives false info once per game. This gives an evil player some leeway in terms of their information, so that they aren''t caught in a lie accidentally.","This fabled is useful for newer players who don''t know how to navigate the latter stages of a game, and might be a good fit thematically in some scripts."],"bluffing":[],"fighting":[],"examples":["The Mercy Society is in play. Town executes the Empath on Day 1, and a good player learns that evil is winning. The next day, town executes the Baron. After killing the Chef, the Demon learns that neither side is winning."],"firstNight":71,"firstNightReminder":"Wake one player and show them the Mercy Society token , as well as a thumbs up, thumbs down, or both.","otherNight":89,"otherNightReminder":"Wake one player and show them the Mercy Society token , as well as a thumbs up, thumbs down, or both.","reminders":["Learns Tonight"],"setup":false,"jinxes":[{"name":"General","align":"good","text":"If the General is in play at the same time as the Mercy Society, evil learns that a General is in play. The General''s information is false once per game.","id":"general"}],"image":"https://menagerie.towerrangers.net/images/peam.png","curata":false,"customBoxes":[{"title":"Credit","content":"Additional credit: Smokey & Annwithaplan"}]}','published','the-menagerie/mercy-society',datetime('now'),datetime('now')),
('pyro','Pyro','loric','Goodpart',NULL,NULL,'The Menagerie','{"slug":"pyro","name":"Pyro","team":"loric","ability":"There are no nominations. At the end of each day, the player with the most players pointing at them is executed. Dead players who point at themselves are not counted.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Papa! Look at the pretty colours in the sky! Wow, that was a big one! Oh... Mr. Morozov must have been tired - he''s fallen asleep.","lede":"The Pyro removes nominations, in favour of something much more explosive.","howToRun":["To activate the Pyro, click its token in the NPCs section.","Run a slightly extended \"afternoon\" chat, but make sure to cut off discussion at timer''s end.","Deduct any spent ghost votes after the countdown, prior to announcing the execution.","In the event of a tie, no-one dies."],"tips":["No nominations means no accusation, no defense, and no majority. Your votes are more crucial than ever! Share your information freely, discuss and puzzle out a solve.","Remember that evil is similarly hamstrung by the Pyro, and so it''s entirely possible to kill the Demon with only a few fingers pointing.","This Loric is recommended for scripts without unseen loss conditions, and therefore not recommended as part of a script containing a Saint, Evil Twin, or Vortox."],"bluffing":[],"fighting":[],"examples":["The Pyro is in play. At the end of the day, the Storyteller counts down: the Oracle has 3 players pointing at them, and the Fang Gu has 2. 8 other players did not vote. A ghost vote is deducted from the Washerwoman, who pointed at the Fang Gu. The Oracle is executed."],"firstNight":0,"firstNightReminder":"","otherNight":0,"otherNightReminder":"","reminders":[],"setup":false,"special":[{"type":"ability","name":"pointing","time":"day"}],"jinxes":[{"name":"Goblin","align":"good","text":"The Goblin must publicly claim to be the Goblin before end of day, instead of during nominations.","id":"goblin"}],"image":"https://menagerie.towerrangers.net/images/Pyro2.png","curata":false}','published','the-menagerie/pyro',datetime('now'),datetime('now')),
('parasitoid','Parasitoid','loric','Goodpart',NULL,NULL,'The Menagerie','{"slug":"parasitoid","name":"Parasitoid","team":"loric","ability":"On Night 1, learn a player. You are in their seat for the purposes of executions and deaths.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"...While this creature feeds upon and grows inside the host creature, should the host be predated upon, the nematomorph is at risk of death.","lede":"The Parasitoid kills players'' hosts, instead of themselves.","howToRun":["It''s good practice to note each \"host\" next to respective players to ensure you don''t make mistakes when assigning kills.","If there is an odd number of players, one player can be their own host, and learn this.","Abilities that prevent death such as the Soldier or Devil''s Advocate are ostensibly \"extended\" to the host. If deaths are announced during the day and the host is protected, announce both. ie. \"Player A is executed and Player B does not die.\""],"tips":["If you''re good, let your host know that you''re their host! If they''re inclined to believe you, they''ll likely do what they can to keep you alive.","If you''re evil, well, while you CAN let your host know, it may also be prudent to hide it. Better yet, perhaps you could consider misdirecting town by stating it''s someone else.","Remember that abilities that prevent an individual from dying affect the host (first player). So, if you''re next to a Tea Lady and want to test yourself, make sure your host is executed, and not yourself."],"bluffing":[],"fighting":[],"examples":["The Parasitoid is in play. Rob, the Steward, learns Nathen, the Ojo, is his host. Rob tells Nathen, and to test the Tea Lady sat next to Rob, town decides to execute Nathen. Nathen does not die, and Rob does not die."],"firstNight":1.5,"firstNightReminder":"Assign a unique player to each seat, and send their name to the player sitting in that seat. In the event of an odd number of players, one player receives their own name.","otherNight":0,"otherNightReminder":"","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/parasite.png","curata":false,"customBoxes":[{"title":"Credit","content":"Additional credit: Cheese"}]}','published','the-menagerie/parasitoid',datetime('now'),datetime('now')),
('present-peeker','Present Peeker','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"present-peeker","name":"Present Peeker","team":"townsfolk","ability":"Each night, learn if a living neighbour has a bad present. If both living neighbours are good, their presents give a boon regardless.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"This one feels soft... must be socks. But this one -- THIS one feels heavy!","lede":"","howToRun":[],"tips":[],"bluffing":[],"fighting":[],"examples":[],"firstNight":37,"firstNightReminder":"Give a thumbs up or thumbs down.","otherNight":57.5,"otherNightReminder":"Give a thumbs up or thumbs down.","reminders":["Boon","Boon"],"setup":false,"image":"https://menagerie.towerrangers.net/images/peekerg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/peekere.png"}','published','the-menagerie/present-peeker',datetime('now'),datetime('now')),
('party-pooper-the-menagerie','Party Pooper','outsider','Goodpart',NULL,NULL,'The Menagerie','{"slug":"party-pooper-the-menagerie","name":"Party Pooper","team":"outsider","ability":"You do not know you are the Party Pooper. You think you are a Townsfolk, but you are not. Presents you give or receive are always a bane.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"So I says... I says... Whatchu talkin'' at me for? You''re not my bozz! Y''know? I zwear, this year has been a total BUST. And y''know what? The turkey was unzh-- un-- it didn''t have any SALT on it.","lede":"","howToRun":[],"tips":[],"bluffing":[],"fighting":[],"examples":[],"firstNight":0,"firstNightReminder":"","otherNight":0,"otherNightReminder":"","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/pooperg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/poopere.png"}','published','the-menagerie/party-pooper',datetime('now'),datetime('now'));